local _, WFJ = ...
WFJ.Data.add("book", {
  ["0a0db49a6c00ab50"] = { "Avendo conosciuto personalmente Edwin VanCleef per tutta la vita, posso dirvi che affrontarlo come nemico è un'impresa assai ardua. Vedete, era il mio amico d'infanzia, e fui io stesso ad addestrarlo nelle arti dell'ombra, pensando che un giorno avrebbe potuto intraprendere una carriera al mio fianco. Se a capo della ⟦Defias Brotherhood=Fratellanza dei Defias⟧ c'è VanCleef, che la Luce abbia pietà delle nostre anime.\n\nMaestro Mathias Shaw\nGilda degli Assassini di ⟦Stormwind=Roccavento⟧", "." },
  ["0a32ecd2ccc1af2d"] = { "Non riuscì a vincolare i Krakken, ma li fece infuriare. Da eoni nessun mortale aveva causato loro dolore, e l'incantesimo del troll era doloroso.\n\nE così si liberarono dei vincoli dell'incantesimo di Min'loth, ma poi ruggirono e colpirono con furia.\n\nSi udì un boato mentre onde immense si levavano dagli abissi e correvano verso la terra. Quando raggiunsero I'lalai, gettarono un'ombra sulla città.\n\nMa prima di distruggerla, i Krakken si fermarono, sospesi.", "." },
  ["0a6dad9dbd99b039"] = { "Gli eserciti dei ⟦Dark Iron=Ferroscuro⟧ si abbatterono sulle roccaforti dei loro cugini e per poco non conquistarono entrambi i regni. Alla fine, però, Madoran Bronzebeard guidò il suo clan a una vittoria decisiva sull'esercito di stregoni di Thaurissan. Thaurissan e i suoi servitori ripiegarono al sicuro nella loro città, ignari di ciò che stava accadendo a Grim Batol, dove l'esercito di Modgud non se la sarebbe cavata meglio contro Khardros e i suoi guerrieri Granmartello.", "." },
  ["0a71086817c1d958"] = { "Quando Arthas e il suo esercito di morti si diressero a sud, a Quel'Thalas non restava un solo elfo vivo. La gloriosa patria degli alti elfi, che aveva resistito per più di novemila anni, non esisteva più.", "." },
  ["0a891dab30b0f788"] = { "Gli eserciti dell'⟦Alliance=Alleanza⟧ guidati da sir Anduin Lothar, Uther il Portatore di Luce e l'ammiraglio Daelin Proudmoore spinsero gli orchi a sud, nella terra devastata di Azeroth, il primo regno caduto sotto l'assalto spietato degli orchi.\n\nLe forze dell'⟦Alliance=Alleanza⟧ al comando di sir Lothar riuscirono a ricacciare i clan di Doomhammer fuori da Lordaeron, di nuovo nelle terre di Azeroth controllate dagli orchi. Le forze di Lothar circondarono la cittadella vulcanica degli orchi, i ⟦Blackrock Spire=Bastioni di Roccianera⟧, e ne assediarono le difese.", "." },
  ["0af5d551eacf6926"] = { "⟦Westfall Stew=Stufato delle Marche Occidentali⟧\n\n3 parti di ⟦Stringy Vulture Meat=Carne d'Avvoltoio Fibrosa⟧ \n3 Musi di Cinghiospino \n3 Occhi di Murloc \n3 Okra\n\nMescola il tutto e porta a ebollizione. Lascia sobbollire per almeno due ore prima di servire.", "." },
})
